// Component layer — generated by line-matcher. Reusable presentation only.
export default function OrderRow({ row, selected, onEdit }) {
  return (
    <tr data-selected={selected ? "true" : undefined}>
      <td>{row.number}</td>
      <td>{row.customer}</td>
      <td className="num">{row.total}</td>
      <td>{row.placedOn}</td>
      <td>Shipped</td>
      <td className="actions">
        <button onClick={() => onEdit(row.id)}>Edit</button>
        <button className="danger">Delete</button>
      </td>
    </tr>
  );
}
